                        if (*value < ' ') goto next;

                        if ((*value == '=') || (*value == '*')) {
                                name_end = value;
                                buffer[value - buffer] = '\0';
                                value++;
                                break;
                        }
                }

                /*
                 *      Skip fields which aren't in "name=value" or "name*value" format.
                 */
                if (!name_end) goto next;

                da = fr_dict_attr_by_name(NULL, fr_dict_root(dict_tacacs), (char *) buffer);
                if (!da) {
